package escuelaing.edu.co.infrastructure.analysis;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import escuelaing.edu.co.domain.model.QueryEntry;
import org.springframework.stereotype.Component;

import jakarta.annotation.PostConstruct;
import java.io.InputStream;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.logging.Logger;

/**
 * Reads the {@code queries.json} file generated by the {@code @SqlQuery}/{@code @Req}
 * annotation processor and builds an immutable in-memory {@code queryId → QueryEntry} map.
 *
 * <p>The map gives the capture environment ({@code SamplingFilter}) and the gate
 * ({@code BenchmarkRunner}, {@link DegradationDetector}) access to each query's
 * performance contract without re-parsing JSON.</p>
 *
 * <p>The file is loaded once at startup from the classpath at
 * {@code loadtest/queries.json}. If it is missing or cannot be parsed, the error is
 * logged and the registry stays empty, so no contract criteria are evaluated.
 * Missing fields default to {@code hasReq=false}, {@code maxResponseTimeMs=1000},
 * {@code priority=MEDIUM} and {@code allowPlanChange=true}.</p>
 */
@Component
public class QueryRegistryLoader {

    private static final Logger LOG = Logger.getLogger(QueryRegistryLoader.class.getName());
    private static final String QUERIES_JSON_PATH = "loadtest/queries.json";

    private final ObjectMapper mapper;
    private Map<String, QueryEntry> registry = Collections.emptyMap();

    public QueryRegistryLoader(ObjectMapper mapper) {
        this.mapper = mapper;
    }

    @PostConstruct
    public void load() {
        InputStream stream = getClass().getClassLoader().getResourceAsStream(QUERIES_JSON_PATH);
        if (stream == null) {
            LOG.warning("[QueryRegistryLoader] " + QUERIES_JSON_PATH +
                    " not found on classpath. SamplingFilter will operate without @Req rules.");
            return;
        }

        try {
            JsonNode root = mapper.readTree(stream);
            JsonNode queriesNode = root.path("queries");

            Map<String, QueryEntry> map = new HashMap<>();
            for (JsonNode q : queriesNode) {
                QueryEntry entry = QueryEntry.builder()
                        .queryId(q.path("queryId").asText())
                        .className(q.path("className").asText())
                        .methodName(q.path("methodName").asText())
                        .queryDescription(q.path("queryDescription").asText())
                        .hasReq(q.path("hasReq").asBoolean(false))
                        .maxResponseTimeMs(q.path("maxResponseTimeMs").asLong(1000L))
                        .priority(q.path("priority").asText("MEDIUM"))
                        .reqDescription(q.path("reqDescription").asText())
                        .allowPlanChange(q.path("allowPlanChange").asBoolean(true))
                        .build();
                map.put(entry.getQueryId(), entry);
            }

            this.registry = Collections.unmodifiableMap(map);
            LOG.info("[QueryRegistryLoader] Loaded " + registry.size() + " entries from " + QUERIES_JSON_PATH);

        } catch (Exception e) {
            LOG.severe("[QueryRegistryLoader] Failed to parse " + QUERIES_JSON_PATH + ": " + e.getMessage());
        }
    }

    public Map<String, QueryEntry> getRegistry() {
        return registry;
    }

    public QueryEntry get(String queryId) {
        return registry.get(queryId);
    }
}
